"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "edge",
        "name": "api-gateway",
        "uid": "uid-deployment-api-gateway"
    },
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 60
        }
    },
    "expected_effect": "The liveness probe will wait longer before checking, allowing the application to start fully before being probed.",
    "rationale": "The pod's liveness probe failed repeatedly during startup (killed_during_startup: true), and the app took 1m2s to run before being killed. The probe's initialDelaySeconds of 10 is too low for the application's startup time. Increasing it to 60 will align the probe timing with the application's startup duration, preventing premature termination.",
